/**
 * Post-process entities generated by typeorm-model-generator.
 *
 * Why:
 * - For some enum columns, the generator emits `default: () => "'E'"`.
 * - In this repo's current TypeORM + MySQL synchronize flow, that default can be
 *   serialized into invalid SQL like: DEFAULT '() => "'E'"'
 *
 * This script normalizes enum defaults to plain strings:
 *   default: () => "'E'"  ->  default: "E"
 */
const fs = require("node:fs/promises");
const path = require("node:path");

async function walk(dir, out) {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      await walk(p, out);
    } else if (e.isFile() && p.endsWith(".ts")) {
      out.push(p);
    }
  }
}

function fixEnumDefaultArrowFn(src) {
  // Only touch @Column("enum", { ... default: () => "'X'" ... })
  // Replace the default with a plain string default: "X"
  return src.replace(
    /@Column\("enum",\s*\{([\s\S]*?)default:\s*\(\)\s*=>\s*"'\s*([^']+?)\s*'"\s*([\s\S]*?)\}\)/g,
    (_m, pre, value, post) => `@Column("enum", {${pre}default: "${value}"${post}})`,
  );
}

async function main() {
  const baseDir =
    process.argv[2] ??
    path.resolve(
      __dirname,
      "..",
      "libs",
      "database",
      "src",
      "entities",
      "entities",
    );

  const files = [];
  await walk(baseDir, files);

  let changed = 0;
  for (const file of files) {
    const before = await fs.readFile(file, "utf8");
    const after = fixEnumDefaultArrowFn(before);
    if (after !== before) {
      await fs.writeFile(file, after, "utf8");
      changed += 1;
      // eslint-disable-next-line no-console
      console.log(`[fix-entities] updated ${file}`);
    }
  }

  // eslint-disable-next-line no-console
  console.log(`[fix-entities] done. changed files: ${changed}`);
}

main().catch((e) => {
  // eslint-disable-next-line no-console
  console.error("[fix-entities] failed", e);
  process.exit(1);
});

